import{_ as l,o as e,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2019-06-27 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-06-27 :: Ceph Performance Meeting","date":"2019-06-27T00:00:00.000Z","updated":"2019-06-28T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","测试","BlueStore","Rados","OpenStack","Jenkins","GitHub"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-27_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-06-27_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-06-27_-_-_Ceph_Performance_Meeting.md"};function s(o,i,a,p,_,c){return e(),t("div",null,[...i[0]||(i[0]=[n("<p>本次会议主要讨论了Ceph分布式存储项目的性能优化和测试进展。以下为会议的关键细节：</p><p><strong>关键细节</strong>：</p><ul><li><strong>调试级别调整</strong>： 讨论将trim和boost的调试级别提高到20以上，并决定将trim整块代码放入单独的调试模块中。</li><li><strong>性能优化</strong>： <ul><li>讨论禁用apptracker可能带来的20%到30%的性能提升。</li><li>分析删除操作优化，发现OST在删除PG时花费大量时间，并讨论优化扫描、预取和预加载到缓存中的策略。</li><li>讨论steno SD或SDHC卡的恢复最大活跃数，并决定增加并发回填以提升性能。</li><li>讨论max backfills和max active之间的关系，并决定进行实验以确定是否需要增加max backfills。</li><li>讨论优化BlueStore缓存，包括避免重复缓存和缓存旋转等。</li></ul></li><li><strong>性能测试</strong>： <ul><li>讨论在硅谷进行性能测试，并计划设置持续性能基准测试。</li><li>讨论Jenkins和GitHub的集成，以及使用GitHub API进行结果发布。</li><li>讨论性能测试标签和回归检测，以及如何确定回归的阈值。</li></ul></li><li><strong>硬件测试</strong>： <ul><li>讨论Intel提供的新Officalis集群，包括TLC和QLC驱动器的配置。</li><li>讨论将节点迁移到Jenkins以进行性能回归测试。</li><li>讨论将高效能节点用于PR测试。</li></ul></li></ul><p><strong>决定事项</strong>：</p><ul><li>将trim和boost的调试级别提高到20以上。</li><li>将trim整块代码放入单独的调试模块中。</li><li>禁用apptracker进行性能测试。</li><li>优化删除操作，包括扫描、预取和预加载。</li><li>增加并发回填以提升性能。</li><li>进行实验以确定是否需要增加max backfills。</li><li>优化BlueStore缓存，包括避免重复缓存和缓存旋转。</li><li>在硅谷进行性能测试，并设置持续性能基准测试。</li><li>使用Jenkins和GitHub进行集成，并发布测试结果。</li><li>使用GitHub API进行结果发布。</li><li>确定性能测试标签和回归检测的阈值。</li><li>使用Intel提供的新Officalis集群进行测试。</li><li>将节点迁移到Jenkins以进行性能回归测试。</li><li>将高效能节点用于PR测试。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>进行trim和boost调试级别调整的测试。</li><li>进行禁用apptracker和优化删除操作的测试。</li><li>进行steno SD或SDHC卡的恢复最大活跃数和max backfills的实验。</li><li>优化BlueStore缓存。</li><li>设置持续性能基准测试。</li><li>完成 Jenkins 和 GitHub 的集成。</li><li>进行性能测试标签和回归检测的测试。</li><li>准备Intel提供的新Officalis集群。</li><li>将节点迁移到 Jenkins。</li><li>将高效能节点用于 PR 测试。</li></ul><p>[改进后的中文总结内容结束]</p>",8)])])}const f=l(r,[["render",s]]);export{m as __pageData,f as default};
